import { useMemo } from 'react';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid,
  Cell,
} from 'recharts';
import type { OptimizeResponse } from '../types';
import { WAIT_BUCKET_LABELS } from '../types';
import RidershipImpact from './RidershipImpact';

/**
 * Bottom drawer: delay distribution chart + route-shift heatmap.
 */

interface Props {
  result: OptimizeResponse | null;
}

function DelayDistributionChart({ result }: { result: OptimizeResponse | null }) {
  const data = useMemo(() => {
    if (!result) return [];
    return WAIT_BUCKET_LABELS.map((label, i) => ({
      bucket: label,
      baseline: result.wait_distribution_baseline[i] ?? 0,
      optimized: result.wait_distribution_optimized[i] ?? 0,
    }));
  }, [result]);

  if (!result) {
    return (
      <div className="flex h-full min-h-[180px] flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-border bg-card-hover/50">
        <div className="text-text-muted">📊</div>
        <div className="text-xs text-text-muted">Run the optimization to see wait time distribution</div>
      </div>
    );
  }

  return (
    <ResponsiveContainer width="100%" height={220}>
      <BarChart data={data} margin={{ top: 8, right: 8, left: -12, bottom: 0 }}>
        <CartesianGrid stroke="#2E2E2E" strokeDasharray="3 3" vertical={false} />
        <XAxis dataKey="bucket" stroke="#9E9E9E" fontSize={11} tickLine={false} axisLine={false} />
        <YAxis stroke="#9E9E9E" fontSize={11} tickLine={false} axisLine={false} />
        <Tooltip
          contentStyle={{
            background: '#1E1E1E',
            border: '1px solid #2E2E2E',
            borderRadius: 8,
            fontSize: 12,
          }}
          labelStyle={{ color: '#EDEDED' }}
        />
        <Legend wrapperStyle={{ fontSize: 12 }} />
        <Bar dataKey="baseline" name="Baseline" fill="#4FC3F7" radius={[3, 3, 0, 0]} />
        <Bar dataKey="optimized" name="Optimized" radius={[3, 3, 0, 0]}>
          {data.map((_, i) => (
            <Cell key={i} fill={i < 5 ? '#00E676' : '#FFAB00'} />
          ))}
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  );
}

function RouteShiftHeatmap({ result }: { result: OptimizeResponse | null }) {
  const rows = useMemo(() => {
    if (!result) return [];
    // The most-shifted routes, sorted by magnitude. Cell intensity reflects the
    // actual offset minutes (the only per-route number the API returns).
    return result.offsets
      .filter((o) => o.offset_minutes !== 0)
      .slice(0, 10)
      .map((o) => ({
        route: `R${o.route_short_name}`,
        shiftedBy: o.offset_minutes,
      }));
  }, [result]);

  if (!result || rows.length === 0) {
    return (
      <div className="flex h-full min-h-[180px] flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-border bg-card-hover/50">
        <div className="text-text-muted">🗺️</div>
        <div className="text-xs text-text-muted">Route shifts will appear here after optimization</div>
      </div>
    );
  }

  const colorFor = (v: number) =>
    v >= 8 ? '#00E676' : v >= 4 ? '#FFAB00' : '#2E2E2E';

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs">
        <thead>
          <tr>
            <th className="sticky left-0 bg-card px-2 py-1.5 text-left font-medium text-text-secondary">
              Route shift
            </th>
            {rows.map((r) => (
              <th key={r.route} className="px-2 py-1.5 text-center font-medium text-text-secondary">
                {r.route}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.route}>
              <td className="sticky left-0 bg-card px-2 py-1.5 font-medium text-text-primary">
                {row.route}{' '}
                <span className="text-text-muted">
                  ({row.shiftedBy > 0 ? '+' : ''}{row.shiftedBy}m)
                </span>
              </td>
              {rows.map((col) => {
                const v = Math.min(12, Math.abs(row.shiftedBy) + Math.abs(col.shiftedBy));
                return (
                  <td key={col.route} className="px-1 py-1 text-center">
                    <div
                      className="mx-auto h-7 w-7 rounded-md"
                      style={{ backgroundColor: colorFor(v), opacity: 0.7 }}
                      title={`${row.route} ↔ ${col.route}: ${v} min combined shift`}
                    />
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function BottomDrawer({ result }: Props) {
  return (
    <div className="flex flex-1 flex-col gap-4 overflow-y-auto rounded-xl border border-border bg-card p-4 min-h-[200px]">
      {result ? (
        <div className="grid grid-cols-1 gap-4 rounded-xl border border-border bg-card p-4 lg:grid-cols-2">
          <div>
            <div className="mb-0.5 text-sm font-semibold text-text-primary">Transfer wait times</div>
            <p className="mb-2 text-[11px] text-text-muted">
              How long riders wait between buses, before vs. after the change.
            </p>
            <DelayDistributionChart result={result} />
          </div>
          <div>
            <div className="mb-0.5 text-sm font-semibold text-text-primary">How routes were adjusted</div>
            <p className="mb-2 text-[11px] text-text-muted">
              Which routes moved, and by how many minutes.
            </p>
            <RouteShiftHeatmap result={result} />
          </div>
        </div>
      ) : (
        <div className="rounded-xl border border-border bg-card p-4">
          <div className="mb-2 text-xs font-semibold text-text-secondary">Charts will appear here</div>
          <p className="text-[11px] text-text-muted">
            After running the optimization, you'll see the wait time distribution and route adjustments below.
          </p>
          <div className="mt-4 grid grid-cols-1 gap-4 lg:grid-cols-2">
            <DelayDistributionChart result={result} />
            <RouteShiftHeatmap result={result} />
          </div>
        </div>
      )}

      <RidershipImpact result={result} />
    </div>
  );
}
