import { lazy, Suspense } from 'react';
import ExplorePanel from '../ExplorePanel';
import OptimizePanel from '../OptimizePanel';
import CircuityPanel from '../CircuityPanel';
import TrunkFeederPanel from '../TrunkFeederPanel';
import TravelPanel from '../TravelPanel';
import BottomDrawer from '../BottomDrawer';
import type { MapEngine, TravelLine, TravelMarker } from '../MapView';

const MapView = lazy(() => import('../MapView'));
import type {
  CircuityGeoJSON,
  CircuitySummaryRoute,
  CorridorGap,
  OptimizeRequest,
  OptimizeResponse,
  TransferNode,
  TravelCompareResponse,
  TravelPoint,
} from '../../types';
import type { ServiceDay, VolumeMode } from '../../lib/persist';

export interface MapWorkspaceProps {
  view: string;
  setView: (v: string) => void;
  // map data
  circuity: CircuityGeoJSON | null;
  nodes: TransferNode[];
  flaggedRoutes: CircuitySummaryRoute[];
  circuityThreshold: number;
  // map layers
  showRoutes: boolean;
  showSplits: boolean;
  showNodes: boolean;
  showProposedNetwork: boolean;
  showOneWay: boolean;
  mapEngine: MapEngine;
  setShowRoutes: (v: boolean) => void;
  setShowSplits: (v: boolean) => void;
  setShowNodes: (v: boolean) => void;
  setShowProposedNetwork: (v: boolean) => void;
  setShowOneWay: (v: boolean) => void;
  setMapEngine: (v: MapEngine) => void;
  corridorSeam: CorridorGap | null;
  setCorridorSeam: (s: CorridorGap | null) => void;
  // routing-adjacent state
  highlightedRoute: string | null;
  setHighlightedRoute: (r: string | null) => void;
  // optimizer
  optimizer: {
    maxShift: number;
    setMaxShift: (v: number) => void;
    bufferMinutes: number;
    setBufferMinutes: (v: number) => void;
    highFreqCutoff: number;
    setHighFreqCutoff: (v: number) => void;
    tMax: number;
    setTMax: (v: number) => void;
    minLayoverMinutes: number;
    setMinLayoverMinutes: (v: number) => void;
    timeLimitSeconds: number;
    setTimeLimitSeconds: (v: number) => void;
    serviceDay: ServiceDay;
    volumeMode: VolumeMode;
    setVolumeMode: (v: VolumeMode) => void;
    running: boolean;
    onRun: () => void;
    result: OptimizeResponse | null;
    onExport: () => void;
    onPlannerReport: () => void;
    downloadPlannerReport: () => void;
    resultServiceDay: ServiceDay | null;
    currentPeriodLabel: string;
    resultPeriodLabel: string | null;
  };
  // travel planner
  travelPicks: {
    origin: TravelPoint | null;
    destination: TravelPoint | null;
    nextPick: 'origin' | 'destination';
  };
  onTravelPicksChange: React.Dispatch<
    React.SetStateAction<{
      origin: TravelPoint | null;
      destination: TravelPoint | null;
      nextPick: 'origin' | 'destination';
    }>
  >;
  serviceDay: ServiceDay;
  onTravelItineraries: (
    itin: Pick<
      TravelCompareResponse,
      'baseline' | 'optimized' | 'origin' | 'destination'
    > | null,
  ) => void;
  travelLines: TravelLine[];
  travelMarkers: TravelMarker[];
  onMapPick: (lat: number, lon: number) => void;
  buildRequest: () => OptimizeRequest;
}

/**
 * The map-centric views (explore / optimize / routes / trunkfeeder / travel):
 * a map section plus a side panel whose contents depend on the active view,
 * with the charts drawer under the optimizer. Pure layout — all state lives
 * in App's hooks and flows in as props.
 */
export default function MapWorkspace({
  view,
  setView,
  circuity,
  nodes,
  flaggedRoutes,
  circuityThreshold,
  showRoutes,
  showSplits,
  showNodes,
  showProposedNetwork,
  showOneWay,
  mapEngine,
  setShowRoutes,
  setShowSplits,
  setShowNodes,
  setShowProposedNetwork,
  setShowOneWay,
  setMapEngine,
  corridorSeam,
  setCorridorSeam,
  highlightedRoute,
  setHighlightedRoute,
  optimizer,
  travelPicks,
  onTravelPicksChange,
  serviceDay,
  onTravelItineraries,
  travelLines,
  travelMarkers,
  onMapPick,
  buildRequest,
}: MapWorkspaceProps) {
  return (
    <div className={`flex ${view === 'optimize' ? 'flex-col' : ''} flex-1 gap-3 overflow-hidden`}>
{/* map — hidden for optimize view to give full width to controls */}
       {view !== 'optimize' && (
         <section className="relative flex-1 overflow-hidden rounded-xl border border-border bg-card">
           <Suspense fallback={null}>
             <MapView
               circuity={circuity}
               nodes={nodes}
               showRoutes={showRoutes}
               // Route quality shows the ORIGINAL routing and its circuity
               // score only — the proposed trunk + feeder splits belong in the
               // Trunk & feeder view (and the Explore toggle).
               showSplits={view === 'trunkfeeder' ? true : showSplits}
               showNodes={view === 'routes' || view === 'trunkfeeder' ? false : showNodes}
               showProposedNetwork={view === 'trunkfeeder' ? showProposedNetwork : false}
               showOneWay={showOneWay}
               highlightedRoute={highlightedRoute}
               engine={mapEngine}
               travelLines={travelLines}
               travelMarkers={travelMarkers}
               onMapPick={onMapPick}
               pickActive={view === 'travel'}
               optimizeShifts={[]}
               corridorSeam={view === 'trunkfeeder' ? corridorSeam : null}
             />
           </Suspense>
         </section>
       )}

      {/* right panel — full width when map is hidden */}
      <aside
        className={`overflow-y-auto rounded-xl border border-border bg-bg p-2 ${
          view === 'optimize' ? 'flex-1 min-h-0' : 'shrink-0 ' + (view === 'travel' ? 'w-96' : 'w-80')
        }`}
      >
        {view === 'explore' && (
          <ExplorePanel
            circuity={circuity}
            showRoutes={showRoutes}
            setShowRoutes={setShowRoutes}
            showSplits={showSplits}
            setShowSplits={setShowSplits}
            showNodes={showNodes}
            setShowNodes={setShowNodes}
            showOneWay={showOneWay}
            setShowOneWay={setShowOneWay}
            mapEngine={mapEngine}
            setMapEngine={setMapEngine}
            highlightedRoute={highlightedRoute}
            setHighlightedRoute={setHighlightedRoute}
          />
        )}
        {view === 'optimize' && (
          <OptimizePanel
            maxShift={optimizer.maxShift}
            setMaxShift={optimizer.setMaxShift}
            bufferMinutes={optimizer.bufferMinutes}
            setBufferMinutes={optimizer.setBufferMinutes}
            highFreqCutoff={optimizer.highFreqCutoff}
            setHighFreqCutoff={optimizer.setHighFreqCutoff}
            tMax={optimizer.tMax}
            setTMax={optimizer.setTMax}
            minLayoverMinutes={optimizer.minLayoverMinutes}
            setMinLayoverMinutes={optimizer.setMinLayoverMinutes}
            timeLimitSeconds={optimizer.timeLimitSeconds}
            setTimeLimitSeconds={optimizer.setTimeLimitSeconds}
            serviceDay={optimizer.serviceDay}
            volumeMode={optimizer.volumeMode}
            setVolumeMode={optimizer.setVolumeMode}
            running={optimizer.running}
            onRun={optimizer.onRun}
            result={optimizer.result}
            onExport={optimizer.onExport}
            onPlannerReport={optimizer.downloadPlannerReport}
            resultServiceDay={optimizer.resultServiceDay}
            currentPeriodLabel={optimizer.currentPeriodLabel}
            resultPeriodLabel={optimizer.resultPeriodLabel}
          />
        )}
        {view === 'routes' && (
          <CircuityPanel
            flaggedRoutes={flaggedRoutes}
            threshold={circuityThreshold}
            highlightedRoute={highlightedRoute}
            onHighlight={setHighlightedRoute}
            circuity={circuity}
            showSplits={showSplits}
            setShowSplits={setShowSplits}
            onOpenTrunkFeeder={() => setView('trunkfeeder')}
          />
        )}
        {view === 'trunkfeeder' && (
          <TrunkFeederPanel
            circuity={circuity}
            flaggedRoutes={flaggedRoutes}
            highlightedRoute={highlightedRoute}
            onHighlight={setHighlightedRoute}
            showProposedNetwork={showProposedNetwork}
            onToggleProposedNetwork={setShowProposedNetwork}
            onCorridorFocus={setCorridorSeam}
          />
        )}
        {view === 'travel' && (
          <TravelPanel
            picks={travelPicks}
            onPicksChange={onTravelPicksChange}
            serviceDay={serviceDay}
            onItineraries={onTravelItineraries}
            optimizerSettings={buildRequest()}
          />
        )}
      </aside>

      {/* charts (transfers only) — inside the flex row so it shares space properly */}
      {view === 'optimize' && <BottomDrawer result={optimizer.result} />}
    </div>
  );
}
